109	/**
110	 * Evaluates the outcome of a user confirmation and dispatches
111	 * policy config updates.
112	 */
113	export async function updatePolicy(
114	  tool: AnyDeclarativeTool,
115	  outcome: ToolConfirmationOutcome,
116	  confirmationDetails: SerializableConfirmationDetails | undefined,
117	  context: AgentLoopContext,
118	  messageBus: MessageBus,
119	  toolInvocation?: AnyToolInvocation,
120	): Promise<void> {
121	  // Mode Transitions (AUTO_EDIT)
122	  if (isAutoEditTransition(tool, outcome)) {
123	    context.config.setApprovalMode(ApprovalMode.AUTO_EDIT);
124	    return;
125	  }
126	
127	  // Determine persist scope if we are persisting.
128	  let persistScope: 'workspace' | 'user' | undefined;
129	  if (outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave) {
130	    // If folder is trusted and workspace policies are enabled, we prefer workspace scope.
131	    if (
132	      context.config &&
133	      context.config.isTrustedFolder() &&
134	      context.config.getWorkspacePoliciesDir() !== undefined
135	    ) {
136	      persistScope = 'workspace';
137	    } else {
138	      persistScope = 'user';
139	    }
140	  }
141	
142	  // Specialized Tools (MCP)
143	  if (confirmationDetails?.type === 'mcp') {
144	    await handleMcpPolicyUpdate(
145	      tool,
146	      outcome,
147	      confirmationDetails,
148	      messageBus,
149	      persistScope,
150	    );
151	    return;
152	  }
153	
154	  // Generic Fallback (Shell, Info, etc.)
155	  await handleStandardPolicyUpdate(
156	    tool,
157	    outcome,
158	    confirmationDetails,
159	    messageBus,
160	    persistScope,
161	    toolInvocation,
162	    context.config,
163	  );
164	}
