44	export const DEFAULT_CORE_POLICIES_DIR = path.join(__dirname, 'policies');
45	
46	// Cache to prevent duplicate warnings in the same process
47	const emittedWarnings = new Set<string>();
48	
49	/**
50	 * Emits a warning feedback event only once per process.
51	 */
52	function emitWarningOnce(message: string): void {
53	  if (!emittedWarnings.has(message)) {
54	    coreEvents.emitFeedback('warning', message);
55	    emittedWarnings.add(message);
56	  }
57	}
58	
59	/**
60	 * Clears the emitted warnings cache. Used primarily for tests.
61	 */
62	export function clearEmittedPolicyWarnings(): void {
63	  emittedWarnings.clear();
64	}
